// Sample application code with lint issues

function calculateTotal(items) {
  let total = 0;  // ESLint: prefer let/const

  for (let i = 0; i < items.length; i++) {  // ESLint: prefer let/const
    total += items[i].price
  }

  return total
}

function formatDate(date) {
  // ESLint: no-unused-vars
  const year = date.getFullYear()
  const month = date.getMonth() + 1
  const day = date.getDate()

  return `${year}-${month}-${day}`
}

function processUser(user) {
  // ESLint: no-console
  console.log("Processing user:", user)

  // ESLint: eqeqeq
  if (user.age == "18") {
    return "adult"
  }

  return "minor"
}

module.exports = { calculateTotal, formatDate, processUser }

// Utility functions with lint issues

// ESLint: no-unused-vars
function unusedFunction() {
  return "This function is never used"
}

function validateEmail(email) {
  // ESLint: no-useless-escape
  const regex = /\S+@\S+\.\S+/
  return regex.test(email)
}

function processData(data) {
  // ESLint: no-var
  const result = []

  for (let i = 0; i < data.length; i++) {
    if (data[i].active) {
      result.push(data[i])
    }
  }

  return result
}

// ESLint: no-shadow
function example() {
  const data = "outer"

  function inner() {
    const data = "inner"  // Shadows outer variable
    return data
  }

  return inner()
}

module.exports = { validateEmail, processData, example }
